{"copy":"<p>Please provide some information about yourself.</p>

<p>The First Name and Last Name you provide will be displayed alongside any comments, forum posts, or ideas you make on the site.</p>

<p>The Email Address and Phone number will not be displayed on the site.</p>

<p>Your Organization and Title are optional. They will be displayed with your comments and forum posts.</p>","customcss":"body{
    background:#fff;
}
form#content_form {
    margin-top: 30px;
}
form .form-control {
    border: 1px solid #CCCCCC;
}
.xrm-attribute-value p {
    font-size: 14px;
    margin: 0;
}
.row .col-md-8 > fieldset {
    margin-top: 20px;
}
#ContentContainer_MainContent_MainContent_ContentBottom_MarketingOptionsPanel .col-md-12 {
    display: flex;
}
#ContentContainer_MainContent_MainContent_ContentBottom_MarketingOptionsPanel .form-check {
    margin: 0 10px;
}
#ContentContainer_MainContent_MainContent_ContentBottom_MarketingOptionsPanel legend {
    font-size: 16px;
    font-weight: 600;
}
span.checkmark {
    left: 0;
    top: 3px;
}
.alert.alert-info.clearfix {
    margin-top: 10px;
    background: #FAE1C8;
}
.alert a.btn.btn-info.btn-sm {
    background: transparent;
    border: none;
    color: #BF7560;
    text-decoration: underline;
    font-weight: 700;
}
.fa-envelope-o:before {
    content: none;
}
.page-heading {
    display: none;
}
.xrm-editable-adx_weblinkset.xrm-entity {
    display: none;
}
footer {
    display: none;
}

/* START PROFILE STYLE */
div#ProfileFormView {
  background-color: transparent;
  border: none;
}
.col-md-4 .well {
  border-radius: 10px;
  background: #fff;
  border: 1px solid #CCCCCC;
}
.col-md-4 .well img {
  border-radius: 10px;
}
.card.nav-profile .card-header {
  border-radius: 12px 12px 0 0;
  background: #BF7560;
  color: #fff;
}
.card.nav-profile {
  border:2px solid #BF7560;
  border-radius: 13px;
}
.card>.list-group:last-child .list-group-item:last-child, .card>.panel-collapse>.list-group:last-child .list-group-item:last-child {
    border-radius: 0 0 18px 18px;
}
#ProfileFormView td.clearfix.cell.text.form-control-cell {
    padding: 0 15px 15px 0;
}
body[data-sitemap-state="/profile/:/"] .page-header {
    border-bottom: 1px solid #CCCCCC;
}
body[data-sitemap-state="/profile/:/"] .list-group-item 
{
background-color:transparent;
}
body[data-sitemap-state="/profile/:/"] .weblinks .list-group-item:first-child
{
    border-radius:10px 10px 0px 0px;
}
body[data-sitemap-state="/profile/:/"] .weblinks .list-group-item:last-child
{
    border-radius:0px 0px 10px 10px;
}
body[data-sitemap-state="/profile/:/"] .fa-exclamation-circle:before
{
    color:#BF7560;
}
body[data-sitemap-state="/profile/:/"] legend
{
    border:0px;
}

#adx_publicprofilecopy, #websiteurl, #jobtitle, 
#nickname, #telephone1, #adx_organizationname, #mobilephone, #emailaddress1,
#lastname, #firstname
{
    border:1px solid #CCCCCC;
    border-radius:10px;
}
#adx_preferredlanguageid_name
{
    border:1px solid #CCCCCC;
    border-radius:10px 0px 0px 10px;
}

/* Added for text of checkbox on profile page */
.checkbox-container span.xrm-attribute-value {
  font-weight: 400;
}

/* Added for adjusting left padding in contact checkboxes on profile page */
.form-check {
  padding-left: 0.2em;
}
/* END PROFILE*/
","customjavascript":"$( document ).ready(function() {
    // Hide marketing preference checkbox for a fax and mail
    $('#ContentContainer_MainContent_MainContent_ContentBottom_MarketingOptionsPanel input[title="Fax"]').parent().parent().parent().hide();
    $('#ContentContainer_MainContent_MainContent_ContentBottom_MarketingOptionsPanel input[title="Mail"]').parent().parent().parent().hide();
    $(".form-check > label").addClass("checkbox-container");
    $(".checkbox-container > span:first-child").append( "<span class='checkmark'></span>" );
    $("#ContentContainer_MainContent_MainContent_ContentBottom_SubmitButton").prop("value","Save & proceed");


    //hiding unwanted fields
    $('#adx_preferredlanguageid_name').parent().parent().parent().hide();
    $('#adx_organizationname').parent().parent().hide();
    $('#telephone1').parent().parent().hide();
    $('#nickname').parent().parent().hide();
    $('#jobtitle').parent().parent().hide();
    $('#websiteurl').parent().parent().hide();
    $('#adx_publicprofilecopy').parent().parent().hide();
    $('#address1_composite').parent().parent().hide();
});","enablerating":false,"enabletracking":false,"excludefromsearch":false,"feedbackpolicy":756150000,"hiddenfromsitemap":true,"isroot":false,"pagetemplateid":"05690323-5fcf-f111-a05a-70a8a52c89ad","parentpageid":"58120917-5fcf-f111-a05a-70a8a52c89ad","partialurl":"profile","publishingstateid":"de110917-5fcf-f111-a05a-70a8a52c89ad","rootwebpageid":"33110b1d-5fcf-f111-a05a-70a8a52c89ad","sharedpageconfiguration":false,"title":"Profile"}
